fn read(p:&Path)->Fallible<Vec<u8>>{let m=fs::symlink_metadata(p).map_err(err)?;if !m.is_file()||m.len()>32*1024*1024{return Err("FILE_CAP".into())}fs::read(p).map_err(err)}
fn payload<'a>(b:&'a[u8],magic:&[u8])->Fallible<&'a[u8]>{if !b.starts_with(magic){return Err("SCHEMA".into())}let e=&b[magic.len()..];if e.len()<65||e[64]!=b'\n'||durable::sha(&e[65..])?.as_bytes()!=&e[..64]{return Err("CHECKSUM".into())}Ok(&e[65..])}
fn atom(root:&Path,b:&[u8])->Fallible<()>{let mut f=OpenOptions::new().write(true).create_new(true).open(root.join("HEAD.next")).map_err(err)?;f.write_all(b).map_err(err)?;f.sync_all().map_err(err)?;fs::rename(root.join("HEAD.next"),root.join("HEAD")).map_err(err)?;File::open(root).and_then(|f|f.sync_all()).map_err(err)}
fn parse_context(bytes:&[u8],depth:usize)->Fallible<(Grid,[f64;3],usize)>{
 if depth>8{return Err("CONTEXT_DEPTH".into())}let mut d=D{b:bytes,i:0};let version=d.text(256)?;let parent_sha=d.text(256)?;let parent_ctx_sha=d.text(256)?;if d.text(256)?!="e34740bf7972cc4bd9223373024450fdb85dab25331e8354e1273701134c2cd0"{return Err("SOURCE_BUILD".into())}let size=d.size(1024*1024)?;let prior=d.take(size)?;let prior_grid=if version=="APPEND_CONTEXT_V2"{if parent_sha!=OLD_SHA||parent_ctx_sha!=CTX_SHA||durable::sha(prior)?!=CTX_SHA{return Err("ANCESTRAL_CONTEXT".into())}None}else if version=="APPEND_CONTEXT_V3"{if parent_sha.len()!=64||durable::sha(prior)?!=parent_ctx_sha{return Err("PARENT_CONTEXT_CHAIN".into())}Some(parse_context(prior,depth+1)?)}else{return Err("CONTEXT_SCHEMA".into())};let size=d.size(1024*1024)?;let mut g=D{b:d.take(size)?,i:0};if g.text(256)?!="OLD_PREFIX_APPEND_POSITIVE_GAUSS4_V1"{return Err("GRID_RULE".into())}let count=g.size(4096)?;let intervals=g.size(4096)?;let base=g.size(512)?;let order=g.size(4)?;let mut nodes=Vec::new();for _ in 0..count{let[x,w]=g.a()?;if w<=0.||nodes.last().is_some_and(|p:&(f64,f64)|p.0>=x){return Err("GRID_POSITIVITY_ORDER".into())}nodes.push((x,w));}if g.i!=g.b.len()||base!=512||order!=4{return Err("GRID_SCHEMA".into())}let values=d.a::<3>()?;let n=d.size(96)?;if d.i!=d.b.len()||![24,48,96].contains(&n)||values[1]<=values[0]{return Err("CONTEXT_CLOCK".into())}if let Some((prior,clock,_))=prior_grid{if nodes.len()<prior.nodes.len()||nodes[..prior.nodes.len()]!=prior.nodes[..]||values[0].to_bits()!=clock[1].to_bits()||values[2].to_bits()!=clock[2].to_bits(){return Err("ANCESTRAL_GRID_EPOCH_PREFIX".into())}for(x,_)in &nodes[prior.nodes.len()..]{if *x-100f64.ln()<=values[0]{return Err("ANCESTRAL_ZERO_PREHISTORY".into())}}}Ok((Grid{nodes,intervals,base,order},values,n))
}
fn parent_state(root:&Path,pinfile:&Path)->Fallible<(coupled::State,f64,Grid,f64,Vec<u8>,String)>{let pin=String::from_utf8(read(pinfile)?).map_err(err)?;let lines=pin.lines().collect::<Vec<_>>();if lines.len()!=4{return Err("PIN_MANIFEST".into())}let bytes=read(&root.join("HEAD"))?;let ctx=read(&root.join("CONTEXT.bin"))?;if durable::sha(&bytes)?!=lines[0]||durable::sha(&ctx)?!=lines[1]{return Err("PIN_PARENT_STATE_CONTEXT".into())}let mut version_reader=D{b:&ctx,i:0};let version=version_reader.text(256)?;if !((lines[3]=="V2"&&version=="APPEND_CONTEXT_V2")||(lines[3]=="V3"&&version=="APPEND_CONTEXT_V3")){return Err("MANIFEST_CONTEXT_SCHEMA_MISMATCH".into())}let (grid,times,n)=parse_context(&ctx,0)?;let run=run_identity::Run::resume(root)?;let magic=if lines[3]=="V2"{b"REI_APPEND_ONLY_SOURCE_SUPPORT_CHECKPOINT_V2\n".as_slice()}else if lines[3]=="V3"{MAGIC}else{return Err("PARENT_SCHEMA".into())};let (k,e,state)=decode_magic(&run,&ctx,lines[2],&grid,times[0],times[1],n,&bytes,magic)?;if k!=n||state.s.to_bits()!=times[1].to_bits(){return Err("PARENT_MUST_ACCEPTED_ENDPOINT".into())}Ok((state,e,grid,times[2],ctx,lines[0].to_string()))}

fn rule(a:f64,b:f64)->Vec<(f64,f64)>{let d=(6f64/5.).sqrt();let x=((3.-2.*d)/7.).sqrt();let y=((3.+2.*d)/7.).sqrt();let wi=(18.+30f64.sqrt())/36.;let wo=(18.-30f64.sqrt())/36.;[(-y,wo),(-x,wi),(x,wi),(y,wo)].into_iter().map(|(v,w)|(a+(b-a)*0.5*(1.+v),(b-a)*0.5*w)).collect()}
fn append(cfg:&HistoryConfig,old:&Grid,a:f64,b:f64,panels:usize)->Fallible<(Grid,f64,f64)>{
 if ![16,32].contains(&panels)||a.to_bits()!=(cfg.start+cfg.max_dln_a).to_bits()||b<=a||b>cfg.end{return Err("APPEND_PREMISE".into())}
 let lo=a+cfg.source.energy_max_ev.ln();let hi=b+cfg.source.energy_max_ev.ln();let mut cuts=vec![lo,hi];
 for j in 0..=96{let t=a+(b-a)*j as f64/96.;for e in [cfg.source.energy_min_ev,cfg.source.energy_max_ev,verner_cutoff_ev(radiation::SPECIES[0]),verner_cutoff_ev(radiation::SPECIES[1]),verner_cutoff_ev(radiation::SPECIES[2])]{let x=t+e.ln();if lo<x&&x<hi{cuts.push(x)}}}cuts.sort_by(f64::total_cmp);cuts.dedup();if panels==32{let mut refined=Vec::new();for ab in cuts.windows(2){let m=(ab[0]+ab[1])*0.5;if !(ab[0]<m&&m<ab[1]){return Err("TAIL_REFINEMENT_GEOMETRY".into())}refined.push(m);}cuts.extend(refined);cuts.sort_by(f64::total_cmp);cuts.dedup();}let mut grid=old.clone();grid.intervals+=cuts.len()-1;
 for ab in cuts.windows(2){for(x,w)in rule(ab[0],ab[1]){if !(x>ab[0]&&x<ab[1]&&w>0.&&x>lo&&x-cfg.source.energy_max_ev.ln()>a){return Err("ZERO_PREHISTORY_OR_POSITIVE_CELL".into())}grid.nodes.push((x,w));}}
 if grid.nodes.len()>4096{return Err(format!("APPEND_CODEC_LIVE_SAMPLE_CAP: old={} added={} total={} cap=4096",old.nodes.len(),grid.nodes.len()-old.nodes.len(),grid.nodes.len()))}if grid.nodes[..old.nodes.len()]!=old.nodes[..]{return Err("APPEND_PREFIX_CHANGED".into())}Ok((grid,lo,hi))
}
fn support(cfg:&HistoryConfig,a:f64,b:f64,lo:f64,hi:f64)->Fallible<()>{if !(lo<=cfg.start+cfg.source.energy_min_ev.ln()&&hi>=b+cfg.source.energy_max_ev.ln()&&a>=cfg.start&&b<=cfg.end){return Err("MISSING_SOURCE_SUPPORT".into())}Ok(())}
fn grid_bytes(g:&Grid)->Vec<u8>{let mut w=W(vec![]);w.text("OLD_PREFIX_APPEND_POSITIVE_GAUSS4_V1");w.n(g.nodes.len()as u64);w.n(g.intervals as u64);w.n(g.base as u64);w.n(g.order as u64);for(x,y)in &g.nodes{w.a(&[*x,*y])}w.0}
fn extend(s:&coupled::State,g:&Grid)->Fallible<coupled::State>{let old=record::state_bytes(s);let mut n=s.clone();n.density.resize_zeros(g.nodes.len());let mut check=n.clone();check.density.truncate(s.density.len());if record::state_bytes(&check)!=old||n.density[s.density.len()..].iter().any(|x|x.to_bits()!=0){return Err("EXACT_STATE_ZERO_EXTENSION".into())}Ok(n)}
fn context(ctx:&[u8],parent_sha:&str,g:&Grid,a:f64,b:f64,n:usize,initial:f64)->Fallible<Vec<u8>>{let mut w=W(vec![]);w.text("APPEND_CONTEXT_V3");w.text(parent_sha);w.text(&durable::sha(ctx)?);w.text("e34740bf7972cc4bd9223373024450fdb85dab25331e8354e1273701134c2cd0");w.n(ctx.len()as u64);w.0.extend(ctx);let gb=grid_bytes(g);w.n(gb.len()as u64);w.0.extend(gb);w.a(&[a,b,initial]);w.n(n as u64);parse_context(&w.0,0)?;Ok(w.0)}
fn clock(a:f64,b:f64,k:usize,n:usize)->f64{if k==0{a}else if k==n{b}else{a+(b-a)*k as f64/n as f64}}
fn decode_magic(run:&run_identity::Run,c:&[u8],exe:&str,g:&Grid,a:f64,b:f64,n:usize,bytes:&[u8],magic:&[u8])->Fallible<(usize,f64,coupled::State)>{run.check_owner()?;if bytes.len()>2*1024*1024{return Err("NEW_ENVELOPE_CAP".into())}let mut d=D{b:payload(bytes,magic)?,i:0};if d.text(65536)?!=run.namespace||d.text(256)?!=exe{return Err("NEW_NAMESPACE_EXE".into())}let nn=d.size(2*1024*1024)?;if d.take(nn)?!=c{return Err("NEW_GRID_SUPPORT_CONTEXT".into())}let k=d.size(n)?;let e=d.f()?;let s=record::read_state(&mut d)?;if d.i!=d.b.len()||s.s.to_bits()!=clock(a,b,k,n).to_bits()||s.density.len()!=g.nodes.len()||!s.accepted_records.is_empty(){return Err("NEW_EPOCH_STATE".into())}Ok((k,e,s))}
fn decode(run:&run_identity::Run,c:&[u8],exe:&str,g:&Grid,a:f64,b:f64,n:usize,bytes:&[u8])->Fallible<(usize,f64,coupled::State)>{decode_magic(run,c,exe,g,a,b,n,bytes,MAGIC)}
fn restore(run:&run_identity::Run,c:&[u8],exe:&str,g:&Grid,a:f64,b:f64,n:usize)->Fallible<(usize,f64,coupled::State)>{decode(run,c,exe,g,a,b,n,&read(&run.root.join("HEAD"))?)}
fn save(run:&run_identity::Run,c:&[u8],exe:&str,g:&Grid,a:f64,b:f64,n:usize,k:usize,e:f64,s:&coupled::State)->Fallible<()>{let mut w=W(vec![]);w.text(&run.namespace);w.text(exe);w.n(c.len()as u64);w.0.extend(c);w.n(k as u64);w.f(e);record::write_state(&mut w,s);let mut bytes=MAGIC.to_vec();bytes.extend(durable::sha(&w.0)?.bytes());bytes.push(b'\n');bytes.extend(w.0);let(pk,pe,ps)=decode(run,c,exe,g,a,b,n,&bytes)?;if pk!=k||pe.to_bits()!=e.to_bits()||record::state_bytes(&ps)!=record::state_bytes(s){return Err("PREPUBLICATION_CODEC_STATE".into())}atom(&run.root,&bytes)?;let(kk,ee,ss)=restore(run,c,exe,g,a,b,n)?;if kk!=k||ee.to_bits()!=e.to_bits()||record::state_bytes(&ss)!=record::state_bytes(s){return Err("NEW_TYPED_ROUNDTRIP".into())}Ok(())}
fn integral(cfg:&HistoryConfig,a:f64,b:f64,n:usize,tail:bool)->Fallible<f64>{let h=(b-a)/n as f64;let mut sum=0.;for i in 0..=n{let s=a+h*i as f64;let p=cfg.background.at_ln_a(s).map_err(err)?;let fraction=if tail{((1./(cfg.source.energy_max_ev*(a-s).exp())-1./cfg.source.energy_max_ev)/(1./cfg.source.energy_min_ev-1./cfg.source.energy_max_ev)).max(0.)}else{1.};let f=cfg.source.photons_per_h_per_s/p.hubble_per_s*fraction;sum+=f*if i==0||i==n{1.}else if i%2==1{4.}else{2.};}Ok(sum*h/3.)}
