const NEW_MAGIC:&[u8]=b"REI_CANONICAL_PARTIAL_CHECKPOINT_V3\n";
fn flat(g:&Grid,t:[f64;3],n:usize)->Vec<u8>{let mut w=W(vec![]);w.text("FLAT_ACCEPTED_CONTEXT_V1");w.n(g.nodes.len()as u64);w.n(g.intervals as u64);w.n(g.base as u64);w.n(g.order as u64);for(x,y)in &g.nodes{w.a(&[*x,*y]);}w.a(&t);w.n(n as u64);w.0}
fn unflat(b:&[u8])->Fallible<(Grid,[f64;3],usize)>{let mut d=D{b,i:0};if d.text(256)?!="FLAT_ACCEPTED_CONTEXT_V1"{return Err("FLAT_SCHEMA".into())}let size=d.size(8192)?;let intervals=d.size(8192)?;let base=d.size(512)?;let order=d.size(4)?;let mut nodes=vec![];for _ in 0..size{let[x,w]=d.a()?;if w<=0.||nodes.last().is_some_and(|p:&(f64,f64)|p.0>=x){return Err("GRID_DOMAIN".into())}nodes.push((x,w));}let times=d.a()?;let n=d.size(96)?;if d.i!=b.len()||![48,96].contains(&n){return Err("FLAT_CLOCK".into())}Ok((Grid{nodes,intervals,base,order},times,n))}
fn canonical_write(w:&mut W,s:&coupled::State)->Fallible<()>{let l=short_hhe_control::v2::owner_ledger(s.radiation).map_err(err)?;for i in 0..13{w.wide(l.terms[i].value);w.wide(l.terms[i].loss);w.n(l.occurrence[i]);w.wide(l.coefficient[i]);}for x in s.active_loss{w.wide(x)}Ok(())}
fn canonical_read(d:&mut D,s:&mut coupled::State)->Fallible<()>{use canonical::{Tracked,Wide};let old=short_hhe_control::v2::owner_ledger(s.radiation).map_err(err)?;let mut terms=[Tracked::empty();13];let mut occurrence=[0;13];let mut coefficient=[Wide::ZERO;13];for i in 0..13{terms[i]=Tracked{value:d.wide()?,loss:d.wide()?};occurrence[i]=d.n()?;coefficient[i]=d.wide()?;if occurrence[i]>0&&(terms[i].loss.is_empty()||coefficient[i].is_empty()){return Err("MISSING_OWNER_LOSS_OR_COEFFICIENT".into())}}let l=short_hhe_control::v2::OwnerLedger{terms,occurrence,coefficient,heat:old.heat,heat_occurrence:old.heat_occurrence,heat_coefficient:old.heat_coefficient};s.radiation.canonical=Some(l);s.active_loss=[d.wide()?,d.wide()?];if short_hhe_control::v2::owner_ledger(s.radiation).map_err(err)?!=l{return Err("CANONICAL_READOUT_STATE_MISMATCH".into())}Ok(())}
fn new_save(root:&Path,c:&[u8],k:usize,e:f64,s:&coupled::State)->Fallible<()>{let mut w=W(vec![]);w.n(c.len()as u64);w.0.extend(c);w.n(k as u64);w.f(e);record::write_state(&mut w,s);canonical_write(&mut w,s)?;let mut b=NEW_MAGIC.to_vec();b.extend(durable::sha(&w.0)?.bytes());b.push(b'\n');b.extend(w.0);if b.len()>16*1024*1024{return Err("CHECKPOINT_CAP_16MIB".into())}let(_,kk,ee,ss)=new_decode(&b)?;let mut x=W(vec![]);let mut y=W(vec![]);canonical_write(&mut x,s)?;canonical_write(&mut y,&ss)?;if kk!=k||ee.to_bits()!=e.to_bits()||record::state_bytes(s)!=record::state_bytes(&ss)||x.0!=y.0{return Err("CANONICAL_ROUNDTRIP".into())}atom(root,&b)}
fn pair_legacy_density(s:&mut coupled::State,g:&Grid)->Fallible<()>{use canonical::Tracked;let c=HHeModel::controlled_fixture();let mut nodes=Vec::with_capacity(g.nodes.len());for (&(eta,_),&number) in g.nodes.iter().zip(s.density.iter()){let n=Tracked::from_f64(number).map_err(err)?;let energy=n.scale(c.ev_erg*(eta-s.s).exp()).map_err(err)?;nodes.push(short_hhe_control::diagnostics::PhotonNode{number:n,energy});}s.density.replace_canonical(nodes).map_err(err)}
fn new_decode(b:&[u8])->Fallible<(Vec<u8>,usize,f64,coupled::State)>{let(version,magic)=if b.starts_with(NEW_MAGIC){(3,NEW_MAGIC)}else if b.starts_with(NEW_MAGIC_V2){(2,NEW_MAGIC_V2)}else if b.starts_with(NEW_MAGIC_V1){(1,NEW_MAGIC_V1)}else{return Err("CANONICAL_CHECKPOINT_SCHEMA".into())};let mut d=D{b:payload(b,magic)?,i:0};let nn=d.size(16*1024*1024)?;let c=d.take(nn)?.to_vec();let(g,t,n)=unflat(&c)?;let k=d.size(n)?;let e=d.f()?;let mut s=match version{1=>record::read_state_v1(&mut d)?,2=>record::read_state_v2(&mut d)?,_=>record::read_state(&mut d)?};canonical_read(&mut d,&mut s)?;if version==1{pair_legacy_density(&mut s,&g)?}if d.i!=d.b.len()||s.s.to_bits()!=clock(t[0],t[1],k,n).to_bits()||s.density.len()!=g.nodes.len()||!s.accepted_records.is_empty(){return Err("NEW_ACCEPTED_CLOCK".into())}Ok((c,k,e,s))}
fn migrate_partial(parent:&Path,root:&Path,n:usize)->Fallible<(Vec<u8>,usize,f64,coupled::State)>{let b=read(&parent.join("HEAD"))?;let ctx=read(&parent.join("CONTEXT.bin"))?;let expected=match parent.file_name().and_then(|x|x.to_str()){Some("h0008-coarse")=>"44f19648bcf13971f51c68fe3c2021ecd469ad0574d6387a8422865da0a8a6a7",Some("h0008-fine-diagnostic")=>"d05c0d519a2cdb628ec449d35955666a1b334efac79ac0ab20a34e7685e276b7",Some("h0008-tail-diagnostic")=>"877550c6cfef949504beb9dd09ee432d229ced2853013f8825962511a10ba1c3",_=>return Err("UNDECLARED_PARTIAL_SOURCE".into())};if durable::sha(&b)?!=expected{return Err("PINNED_IMMUTABLE_PARTIAL_HEAD".into())}let(g,t,pn)=parse_context(&ctx,0)?;if pn!=n{return Err("PARTIAL_STEP_COUNT".into())}let mut d=D{b:payload(&b,MAGIC)?,i:0};let _ns=d.text(65536)?;let exe=d.text(256)?;let receipt=String::from_utf8(read(&parent.join("MIGRATION.json"))?).map_err(err)?;if !receipt.contains(&format!("\"exe_sha\":\"{exe}\"")){return Err("PARTIAL_SOURCE_EXE".into())}let len=d.size(16*1024*1024)?;if d.take(len)?!=ctx{return Err("PARTIAL_CONTEXT".into())}let k=d.size(n)?;let e=d.f()?;let mut s=record::read_state_v1(&mut d)?;pair_legacy_density(&mut s,&g)?;if d.i!=d.b.len()||k==0||k>=n||s.s.to_bits()!=clock(t[0],t[1],k,n).to_bits()||s.density.len()!=g.nodes.len()||!s.accepted_records.is_empty(){return Err("PARTIAL_STATE_DOMAIN".into())}let c=flat(&g,t,n);fs::create_dir(root).map_err(err)?;new_save(root,&c,k,e,&s)?;fs::write(root.join("CONTEXT.bin"),&c).map_err(err)?;fs::write(root.join("MIGRATION.json"),format!("{{\"old_head_sha\":{:?},\"old_context_sha\":{:?},\"old_exe_sha\":{:?},\"partial_step\":{},\"n\":{},\"gas_epoch_grid_owners_preserved\":true,\"historical_loss\":\"NOT_MEASURED_IN_OLD_BINARY64_CHECKPOINT\",\"old_cost_evidence_preserved\":true}}\n",durable::sha(&b)?,durable::sha(&ctx)?,exe,k,n)).map_err(err)?;Ok((c,k,e,s))}
fn run()->Fallible<()>{let args:Vec<_>=std::env::args().collect();if args.len()!=6{return Err("migrate-partial|resume parent newroot n end".into())}let mode=&args[1];let parent=Path::new(&args[2]);let root=Path::new(&args[3]);let n:usize=args[4].parse().map_err(err)?;let end:usize=args[5].parse().map_err(err)?;let mut cfg=parse_config(CONFIG).map_err(err)?;record::set_enabled(false);let before=counts();let(c,first,mut elapsed,mut state)=if mode=="migrate-partial"{migrate_partial(parent,root,n)?}else if mode=="resume"{new_decode(&read(&root.join("HEAD"))?)?}else{return Err("MODE".into())};let(grid,t,nn)=unflat(&c)?;if nn!=n||end<first||end>n||counts()!=before{return Err("PURE_MIGRATION_OR_STEP_RANGE".into())}cfg.max_dln_a=t[1]-cfg.start;let mut history=OpenOptions::new().write(true).create_new(true).open(root.join(format!("history_{first}_{end}.csv"))).map_err(err)?;writeln!(history,"{}",output::HEADER).map_err(err)?;let mut steps=File::create(root.join(format!("steps_{first}_{end}.csv"))).map_err(err)?;writeln!(steps,"k,s,norm,n_ratio,e_ratio,RHS,sigma,evaluations").map_err(err)?;let mut maxima=[state.norm,state.n_ratio,state.e_ratio];let engine=counts();for k in first+1..=end{let target=clock(t[0],t[1],k,n);let c0=counts();let old=record::state_bytes(&state);let next=match coupled::advance(&cfg,&grid,&state,target,t[2]){Ok(x)=>x,Err(e)=>{if record::state_bytes(&state)!=old{return Err("REJECTED_STATE_CHANGED".into())}fs::write(root.join(format!("FAILURE_{k}.json")),format!("{{\"reason\":{:?},\"last_epoch\":{:?},\"last_step\":{},\"attempted_step\":{},\"counts\":{:?},\"state_unchanged\":true}}\n",e,state.s,k-1,k,delta(c0,counts()))).map_err(err)?;return Err(e)}};let p=cfg.background.at_ln_a((state.s+next.s)*0.5).map_err(err)?;elapsed+=(next.s-state.s)/p.hubble_per_s;state=next;for(i,v)in[state.norm,state.n_ratio,state.e_ratio].into_iter().enumerate(){if v>1.||!v.is_finite(){return Err("ORIGINAL_GATE_WITH_CANONICAL_LOSS".into())}maxima[i]=maxima[i].max(v)}new_save(root,&c,k,elapsed,&state)?;let science=counts();let row=output::row(&cfg,&grid,&state,t[2])?;let observer=delta(science,counts());output::write_row(&mut history,&row)?;history.flush().map_err(err)?;writeln!(steps,"{k},{:.17e},{:.17e},{:.17e},{:.17e},{},{},{}",state.s,state.norm,state.n_ratio,state.e_ratio,delta(c0,counts())[0],delta(c0,counts())[1],delta(c0,counts())[2]).map_err(err)?;steps.flush().map_err(err)?;println!("ACCEPTED k={k} observer={observer:?} Gamma_representation_bound={:?} gates={:?}",*radiation::LAST_GAMMA_BOUND.lock().map_err(err)?,[state.norm,state.n_ratio,state.e_ratio]);}
 let row=output::row(&cfg,&grid,&state,t[2])?;let mut f=File::create(root.join(format!("endpoint_{end}.csv"))).map_err(err)?;writeln!(f,"{}",output::HEADER).map_err(err)?;output::write_row(&mut f,&row)?;
 let ni=integral(&cfg,t[0],state.s,128,false)?;let mean=HHeModel::controlled_fixture().ev_erg*(cfg.source.energy_max_ev/cfg.source.energy_min_ev).ln()/(1./cfg.source.energy_min_ev-1./cfg.source.energy_max_ev);
 // Source comparison includes old accepted prefix of this horizon; preserve original base.
 let receipt=format!("{{\"first_step\":{},\"last_step\":{},\"new_advances\":{},\"nodes\":{},\"n\":{},\"epoch\":{:?},\"redshift\":{:?},\"elapsed_s\":{:?},\"maximum_original_gate_ratios_including_new_loss\":{:?},\"counts\":{:?},\"phase_counts_with_observer\":{:?},\"source_simpson128\":{:?},\"source_mean_energy_erg\":{:?},\"old_historical_loss\":\"NOT_MEASURED\",\"physical_claim\":\"HOLD\"}}\n",first,end,end-first,grid.nodes.len(),n,state.s,row[1],elapsed,maxima,counts(),delta(engine,counts()),ni,mean);fs::write(root.join(format!("PHASE_{first}_{end}.json")),&receipt).map_err(err)?;println!("{receipt}");Ok(())}
fn main(){if let Err(e)=run(){eprintln!("CANONICAL_REFUSAL {e}; COUNTS={:?}",counts());std::process::exit(2)}}
